parameters.functionCode:
// 5. NODO DECISOR INTELIGENTE
// Cruza productos, eventos del calendario y reglas para determinar la mejor promoción
const items = $input.all();
const hoy = new Date().toISOString().split('T')[0];

// Extraer datos desde los nodos previos
const productos = $('2. Supabase: Productos Activos').all().map(i => i.json);
const eventos = $('3. Supabase: Eventos Calendario').all().map(i => i.json);
const reglas = $('4. Supabase: Reglas Activas').all().map(i => i.json).sort((a,b) => (b.prioridad || 0) - (a.prioridad || 0));

if (!productos.length) {
  throw new Error('No se encontraron productos activos.');
}

// 1. Buscar evento activo hoy o en los próximos 7 días
const eventoActual = eventos.find(e => {
  const ini = e.fecha_inicio;
  const fin = e.fecha_fin;
  return hoy >= ini && hoy <= fin;
}) || eventos[0] || null;

let productoElegido = null;
let reglaElegida = null;
let descuento = 10;
let motivo = 'Promoción sugerida por rotación general';

// Si hay evento, priorizar productos relacionados
if (eventoActual && eventoActual.productos_relacionados && eventoActual.productos_relacionados.length > 0) {
  productoElegido = productos.find(p => 
    eventoActual.productos_relacionados.some(rel => p.nombre.toLowerCase().includes(rel.toLowerCase()))
  );
  if (productoElegido) {
    reglaElegida = reglas.find(r => r.condicion?.tipo === 'evento_calendario') || reglas[0];
    descuento = reglaElegida ? reglaElegida.descuento_min || 15 : 15;
    motivo = `Asociado al evento: ${eventoActual.nombre}`;
  }
}

// Si no se encontró por evento, seleccionar por mayor precio o destacado
if (!productoElegido) {
  productoElegido = productos.find(p => p.is_featured) || productos[0];
  reglaElegida = reglas[0] || { id: null, nombre: 'Regla Estándar', descuento_min: 10, descuento_max: 15 };
  descuento = reglaElegida.descuento_min || 10;
  motivo = 'Promoción de fidelización / producto estrella';
}

const precioOriginal = Number(productoElegido.precio_venta) || 25000;
const precioFinal = Math.round(precioOriginal * (1 - descuento / 100));

return [{
  json: {
    decision_timestamp: new Date().toISOString(),
    producto: productoElegido,
    regla: reglaElegida,
    evento: eventoActual,
    descuento_aplicado: descuento,
    precio_original: precioOriginal,
    precio_final: precioFinal,
    motivo: motivo
  }
}];

// 6. GENERADOR DE PROMPTS PARA IMAGEN Y TEXTO
const decision = $input.first().json;
const p = decision.producto;
const d = decision.descuento_aplicado;
const ev = decision.evento;

const imagePrompt = `Foto profesional publicitaria para Instagram de ${p.nombre}, panadería artesanal gourmet 100% sin gluten (Sin TACC). Estilo cálido, fondo de madera rústica con harina de arroz espolvoreada suavemente, iluminación de estudio gastronómico con banner elegante que indica ${d}% OFF. Alta definición 8k, apetitoso y fresco recién horneado.`;

const textPrompt = `Actúa como el Director de Marketing de PanFree (Encarnación, Paraguay). Redacta un copy publicitario para Instagram con gancho atractivo, emojis, llamado a la acción y hashtags para ${p.nombre} con un ${d}% de descuento especial por ${ev ? ev.nombre : 'promoción de la semana'}. Precio promocional: G/ ${Number(decision.precio_final).toLocaleString('es-PY')}. Pedidos en panfree.fit o WhatsApp al +595 984 589845.`;

return [{
  json: {
    ...decision,
    image_prompt: imagePrompt,
    text_prompt: textPrompt
  }
}];

